<template>
  <div class="history">
    <div class="wrap">
      <header class="topbar">
        <router-link :to="backLink" class="icon-link" aria-label="Tilbage til scoreboard" title="Tilbage">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18l-6-6 6-6" /></svg>
        </router-link>
        <div class="brand">
          <svg width="30" height="30" viewBox="0 0 48 48" aria-hidden="true">
            <rect x="0" y="0" width="48" height="48" rx="12" fill="#5B95FF" />
            <path d="M15 10v28M15 10h10a7 7 0 0 1 0 14H15M15 24h12a7 7 0 0 1 0 14H15" fill="none" stroke="#0E0F12" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round" />
            <circle cx="25" cy="17" r="2.6" fill="#0E0F12" />
          </svg>
          <h1 class="page-title">HISTORIK</h1>
        </div>
        <div class="spacer"></div>
      </header>

      <p v-if="loading" class="empty">Henter kampe…</p>

      <div v-else-if="matches.length === 0 && cricketMatches.length === 0" class="empty-card">
        <h2>Ingen kampe endnu</h2>
        <p>En kamp gemmes automatisk, så snart det første leg er vundet. Tryk "Ny kamp" for at afslutte en kamp og starte en ny.</p>
      </div>

      <template v-else>
        <div class="tabs" role="tablist" aria-label="Visning">
          <button v-if="matches.length" type="button" role="tab" :aria-selected="tab === 'overview' ? 'true' : 'false'" :class="{ selected: tab === 'overview' }" @click="tab = 'overview'">Overblik</button>
          <button v-if="matches.length" type="button" role="tab" :aria-selected="tab === 'player' ? 'true' : 'false'" :class="{ selected: tab === 'player' }" @click="tab = 'player'">Spiller</button>
          <button v-if="cricketMatches.length" type="button" role="tab" :aria-selected="tab === 'cricket' ? 'true' : 'false'" :class="{ selected: tab === 'cricket' }" @click="tab = 'cricket'">Cricket</button>
        </div>

        <!-- ================= CRICKET ================= -->
        <template v-if="tab === 'cricket'">
          <section class="block">
            <h2 class="section-title">CRICKET · STILLING</h2>
            <div class="c-table">
              <div class="c-row c-head">
                <span>Spiller</span><span>Kampe</span><span>Sejre</span><span>MPR</span>
              </div>
              <div v-for="r in cricketTable" :key="r.name" class="c-row">
                <span class="c-name">{{ r.name }}</span><span>{{ r.matches }}</span><span>{{ r.wins }}</span><span>{{ r.mpr }}</span>
              </div>
            </div>
          </section>
          <section class="block">
            <h2 class="section-title">CRICKET · KAMPE</h2>
            <ul class="matches">
              <li v-for="m in cricketMatches" :key="m.id" class="match">
                <div class="match-head">
                  <span class="match-date">{{ formatDate(m.startedAt) }} · {{ cricketModeLabel(m) }}</span>
                  <span class="match-tools">
                    <button type="button" class="delete" :aria-label="'Slet cricket-kamp ' + formatDate(m.startedAt)" @click="deleteCricket(m)">
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18" /><path d="M8 6V4h8v2" /><path d="M19 6l-1 14H6L5 6" /></svg>
                      Slet
                    </button>
                  </span>
                </div>
                <ul class="multi-body">
                  <li v-for="p in m.list" :key="p.key" :class="{ won: p.won }">
                    <span class="ms-name">{{ p.name }}</span>
                    <span class="ms-avg">MPR {{ p.mpr }}</span>
                    <span class="ms-legs">{{ p.legs }}</span>
                  </li>
                </ul>
              </li>
            </ul>
          </section>
        </template>

        <!-- ================= PLAYER ================= -->
        <template v-else-if="tab === 'player'">
          <section class="block">
            <label class="picker-field">
              <span class="sr-only">Vælg spiller</span>
              <select v-model="profileName" @change="onProfilePick">
                <option v-for="n in names" :key="'p-' + n" :value="n">{{ n }}</option>
              </select>
            </label>
            <div class="tiles">
              <div v-for="t in tiles" :key="t.label" class="tile">
                <span class="tile-value" :class="{ gold: t.gold }">{{ t.value }}</span>
                <span class="tile-label">{{ t.label }}</span>
              </div>
            </div>
          </section>

          <section class="block">
            <div class="chart-head">
              <h2 class="section-title">UDVIKLING</h2>
              <div class="seg-small" role="group" aria-label="Vis">
                <button type="button" :class="{ selected: metric === 'avg' }" :aria-pressed="metric === 'avg' ? 'true' : 'false'" @click="metric = 'avg'">Gennemsnit</button>
                <button type="button" :class="{ selected: metric === 'co' }" :aria-pressed="metric === 'co' ? 'true' : 'false'" @click="metric = 'co'">Checkout %</button>
              </div>
            </div>
            <div class="card chart-card">
              <PlayerChart v-if="chartPoints.length >= 2" :points="chartPoints" :title="metric === 'avg' ? 'Gennemsnit pr. kamp' : 'Checkout % pr. kamp'" :suffix="metric === 'co' ? '%' : ''" />
              <p v-else class="chart-empty">{{ metric === 'co' ? 'Checkout % kræver mindst 2 kampe, hvor der er svaret på darts på double.' : 'Spil mindst 2 kampe for at se en graf.' }}</p>
            </div>
          </section>

          <section class="block">
            <h2 class="section-title">BADGES <span class="count">{{ earnedCount }}/{{ badges.length }}</span></h2>
            <div class="badges">
              <div v-for="b in badges" :key="b.id" class="badge" :class="{ earned: b.earned }">
                <span class="badge-icon">
                  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path :d="iconPaths[b.icon]" /></svg>
                </span>
                <span class="badge-text">
                  <span class="badge-name">{{ b.name }}</span>
                  <span class="badge-desc">{{ b.desc }}</span>
                  <span v-if="b.earned && b.date" class="badge-date">Opnået {{ formatDate(b.date) }}</span>
                  <span v-else-if="b.progress" class="badge-progress">
                    <span class="bar"><span :style="{ width: (b.progress.have / b.progress.need * 100) + '%' }"></span></span>
                    {{ b.progress.have }}/{{ b.progress.need }}
                  </span>
                </span>
              </div>
            </div>
          </section>

          <section class="block">
            <h2 class="section-title">KAMPE</h2>
            <ul class="matches">
              <li v-for="e in profileListNewest" :key="'pm-' + e.id" class="match">
                <div class="match-head">
                  <span class="match-date">{{ formatDate(e.date) }} · {{ e.startScore }}</span>
                  <span class="result-tag" :class="e.result">{{ e.result === 'win' ? 'SEJR' : (e.result === 'loss' ? 'TAB' : 'UAFGJORT') }}</span>
                </div>
                <div class="match-body">
                  <div class="match-player won">
                    <span class="mp-name">{{ e.me.name }}</span>
                    <span class="mp-avg">AVG {{ formatNumber(e.avg) }}</span>
                  </div>
                  <div class="match-legs">
                    <span :class="{ lead: e.myLegs > e.oppLegs }">{{ e.myLegs }}</span>
                    <span class="dash">–</span>
                    <span :class="{ lead: e.oppLegs > e.myLegs }">{{ e.oppLegs }}</span>
                  </div>
                  <div class="match-player right">
                    <span class="mp-name">{{ e.oppName }}</span>
                    <span class="mp-avg">AVG {{ formatNumber(average(e.opp.scored, e.opp.visits)) }}</span>
                  </div>
                </div>
              </li>
            </ul>
          </section>
        </template>

        <!-- ================= OVERVIEW ================= -->
        <template v-else>
        <!-- Head-to-head -->
        <section class="block">
          <h2 class="section-title">HEAD-TO-HEAD</h2>
          <div class="h2h-pickers">
            <label class="picker-field">
              <span class="sr-only">Spiller A</span>
              <select v-model="playerA">
                <option v-for="n in names" :key="'a-' + n" :value="n">{{ n }}</option>
              </select>
            </label>
            <span class="vs">VS</span>
            <label class="picker-field">
              <span class="sr-only">Spiller B</span>
              <select v-model="playerB">
                <option v-for="n in names" :key="'b-' + n" :value="n">{{ n }}</option>
              </select>
            </label>
          </div>

          <div v-if="h2h.matches.length === 0" class="empty-card small">
            <p>{{ playerA }} og {{ playerB }} har ikke spillet mod hinanden endnu.</p>
          </div>

          <div v-else class="card">
            <div class="h2h-score">
              <div class="h2h-side">
                <div class="h2h-name">{{ playerA }}</div>
                <div class="h2h-big" :class="{ lead: h2h.a.matchWins > h2h.b.matchWins }">{{ h2h.a.matchWins }}</div>
              </div>
              <div class="h2h-mid">
                <div class="h2h-label">KAMPE</div>
                <div class="h2h-dash">–</div>
                <div v-if="h2h.draws" class="h2h-draws">{{ h2h.draws }} uafgjort</div>
              </div>
              <div class="h2h-side right">
                <div class="h2h-name">{{ playerB }}</div>
                <div class="h2h-big" :class="{ lead: h2h.b.matchWins > h2h.a.matchWins }">{{ h2h.b.matchWins }}</div>
              </div>
            </div>

            <div class="rows">
              <div v-for="row in h2hRows" :key="row.label" class="row">
                <span :class="{ win: row.winner === 'a' }">{{ row.a }}</span>
                <span class="row-label">{{ row.label }}</span>
                <span :class="{ win: row.winner === 'b' }">{{ row.b }}</span>
              </div>
            </div>
          </div>
        </section>

        <!-- Records -->
        <section class="block">
          <h2 class="section-title">REKORDER</h2>
          <div class="records">
            <div v-for="r in recordCards" :key="r.label" class="record">
              <div class="record-label">{{ r.label }}</div>
              <div class="record-value" :class="{ gold: r.gold }">{{ r.value }}</div>
              <div class="record-who">{{ r.who }}</div>
            </div>
          </div>
        </section>

        <!-- Match list -->
        <section class="block">
          <h2 class="section-title">KAMPE</h2>
          <ul class="matches">
            <li v-for="m in matches" :key="m.id" class="match">
              <div class="match-head">
                <span class="match-date">{{ formatDate(m.startedAt) }} · {{ m.startScore || 501 }}<template v-if="m.mode === 'local'"> · {{ m.teams ? 'Hold' : 'Lokalt' }}</template></span>
                <span class="match-tools">
                  <span v-if="m.id === currentMatchId" class="live-tag">I GANG</span>
                  <button type="button" class="delete" :aria-label="'Slet kamp ' + formatDate(m.startedAt)" @click="deleteMatch(m)">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18" /><path d="M8 6V4h8v2" /><path d="M19 6l-1 14H6L5 6" /></svg>
                    Slet
                  </button>
                </span>
              </div>
              <!-- 3-4 players or teams: one row per side, most legs first -->
              <ul v-if="!isOneVsOne(m)" class="multi-body">
                <li v-for="side in matchSides(m)" :key="side.key" :class="{ won: side.won }">
                  <span class="ms-name">{{ side.name }}</span>
                  <span class="ms-avg">AVG {{ formatNumber(side.avg) }}</span>
                  <span class="ms-legs">{{ side.legs }}</span>
                </li>
              </ul>
              <div v-else class="match-body">
                <div class="match-player" :class="{ won: m.players.p1.legs > m.players.p2.legs }">
                  <span class="mp-name">{{ m.players.p1.name }}</span>
                  <span class="mp-avg">AVG {{ formatNumber(average(m.players.p1.scored, m.players.p1.visits)) }}</span>
                </div>
                <div class="match-legs">
                  <span :class="{ lead: m.players.p1.legs > m.players.p2.legs }">{{ m.players.p1.legs }}</span>
                  <span class="dash">–</span>
                  <span :class="{ lead: m.players.p2.legs > m.players.p1.legs }">{{ m.players.p2.legs }}</span>
                </div>
                <div class="match-player right" :class="{ won: m.players.p2.legs > m.players.p1.legs }">
                  <span class="mp-name">{{ m.players.p2.name }}</span>
                  <span class="mp-avg">AVG {{ formatNumber(average(m.players.p2.scored, m.players.p2.visits)) }}</span>
                </div>
              </div>
            </li>
          </ul>
          <button type="button" class="delete-all" @click="deleteAll">Slet alle kampe</button>
        </section>
        </template>
      </template>
    </div>
  </div>
</template>

<script>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue';
import { useRoute } from 'vue-router';
import { getDatabase, ref as firebaseRef, onValue, remove, update } from 'firebase/database';
import {
  matchList, playerNames, headToHead, records, average, formatNumber, formatPct, formatDate, normalizeName,
  playerMatches, playerSummary, computeBadges, allPlayers, isOneVsOne,
} from '@/matchHistory';
import { showConfirm } from '@/dialog';
import { local } from '@/settings';
import PlayerChart from '@/components/PlayerChart.vue';

const ICON_PATHS = {
  trophy: 'M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0V4zM17 5h3v2a3 3 0 0 1-3 3M7 5H4v2a3 3 0 0 0 3 3',
  shield: 'M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6l8-3z',
  flame: 'M12 3c1 4 5 5 5 10a5 5 0 0 1-10 0c0-3 2-4 2-6 1 1 2 2 2 3 0-3 1-5 1-7z',
  bolt: 'M13 2L4 14h7l-1 8 9-12h-7l1-8z',
  chart: 'M4 20V10M10 20V4M16 20v-7M2 20h20',
  target: 'M3 12a9 9 0 1 0 18 0a9 9 0 1 0-18 0M7 12a5 5 0 1 0 10 0a5 5 0 1 0-10 0M11 12a1 1 0 1 0 2 0a1 1 0 1 0-2 0',
  crown: 'M3 8l4 4 5-7 5 7 4-4-2 11H5L3 8z',
  clock: 'M3 12a9 9 0 1 0 18 0a9 9 0 1 0-18 0M12 7v5l3 2',
  star: 'M12 3l2.8 5.7 6.2.9-4.5 4.4 1 6.2L12 17.3l-5.5 2.9 1-6.2L3 9.6l6.2-.9L12 3z',
  bot: 'M5 8h14v11H5zM12 4v4M9 13h.01M15 13h.01M10 16h4',
  calendar: 'M4 6h16v14H4zM4 10h16M9 3v4M15 3v4',
  medal: 'M8 3l2.5 6M16 3l-2.5 6M6 15a6 6 0 1 0 12 0a6 6 0 1 0-12 0M12 13v4',
};

export default {
  components: { PlayerChart },
  setup() {
    const route = useRoute();
    const database = getDatabase();
    const tab = ref('overview');
    const metric = ref('avg');
    const profileName = ref('');
    const loading = ref(true);
    const raw = ref(null);
    const currentMatchId = ref(null);
    const scoreboardNames = ref([]);
    const playerA = ref('');
    const playerB = ref('');
    const unsubscribers = [];

    const backLink = computed(() => ({ path: '/', query: route.query }));
    const matches = computed(() => matchList(raw.value));

    // ---- cricket (stored separately under history/cricket)
    const rawCricket = ref(null);
    const fmtMpr = (marks, visits) => (visits ? (marks / visits).toFixed(2) : '–');
    const cricketMatches = computed(() => Object.entries(rawCricket.value || {})
      .map(([id, m]) => {
        const ps = ['p1', 'p2', 'p3', 'p4'].map(k => (m.players || {})[k]).filter(Boolean);
        const top = Math.max(0, ...ps.map(p => p.legs || 0));
        const leaders = ps.filter(p => (p.legs || 0) === top).length;
        const list = ps.map((p, i) => ({
          key: `p${i}`, name: p.name, legs: p.legs || 0, marks: p.marks || 0, visits: p.visits || 0,
          mpr: fmtMpr(p.marks || 0, p.visits || 0), won: top > 0 && (p.legs || 0) === top && leaders === 1,
        })).sort((a, b) => b.legs - a.legs);
        return { ...m, id, list };
      })
      .filter(m => m.list.length)
      .sort((a, b) => (b.startedAt || 0) - (a.startedAt || 0)));
    const cricketTable = computed(() => {
      const by = new Map();
      cricketMatches.value.forEach((m) => {
        m.list.forEach((p) => {
          const k = normalizeName(p.name);
          const r = by.get(k) || { name: p.name, matches: 0, wins: 0, marks: 0, visits: 0 };
          r.matches += 1;
          if (p.won) r.wins += 1;
          r.marks += p.marks;
          r.visits += p.visits;
          by.set(k, r);
        });
      });
      return [...by.values()]
        .map(r => ({ ...r, mpr: fmtMpr(r.marks, r.visits) }))
        .sort((a, b) => (b.wins - a.wins) || (b.matches - a.matches));
    });
    const cricketModeLabel = (m) => {
      const mode = { local: 'Lokalt', ai: 'Mod AI', online: 'Online' }[m.mode] || 'Cricket';
      const kind = m.variant === 'standard' ? 'Cricket' : 'Cut-throat';
      return `${kind} · ${mode}${m.order === 'strict' ? ' · 20→15' : ''}`;
    };
    const deleteCricket = async (m) => {
      const label = m.list.map(p => `${p.name} ${p.legs}`).join(', ');
      if (await showConfirm(`${label}, ${formatDate(m.startedAt)}.`, { title: 'Slet kamp?', confirmText: 'Slet', danger: true })) {
        remove(firebaseRef(database, `history/cricket/${m.id}`));
      }
    };
    watch([matches, cricketMatches], () => {
      if (!matches.value.length && cricketMatches.value.length) tab.value = 'cricket';
    });
    const names = computed(() => playerNames(matches.value));

    // Default the head-to-head to the two players on the scoreboard, else the
    // pair from the most recent match.
    const pickDefaults = () => {
      if (playerA.value && playerB.value) return;
      const list = names.value;
      const find = (n) => list.find(x => normalizeName(x) === normalizeName(n));
      const [s1, s2] = scoreboardNames.value.map(find);
      if (s1 && s2 && s1 !== s2) {
        playerA.value = s1;
        playerB.value = s2;
      } else if (matches.value.length) {
        playerA.value = find(matches.value[0].players.p1.name) || list[0] || '';
        playerB.value = find(matches.value[0].players.p2.name) || list[1] || '';
      }
    };
    watch([names, scoreboardNames], pickDefaults);

    const h2h = computed(() => headToHead(matches.value, playerA.value, playerB.value));

    // ---- player profile
    // Keep re-picking the default until the user chooses a player themselves,
    // because history and scoreboard names can arrive in either order.
    let profilePickedByUser = false;
    watch([names, scoreboardNames], () => {
      if (profilePickedByUser && names.value.includes(profileName.value)) return;
      const find = (n) => names.value.find(x => normalizeName(x) === normalizeName(n));
      const seatName = local.seat ? scoreboardNames.value[local.seat - 1] : '';
      profileName.value = find(local.name) || find(seatName) || find(scoreboardNames.value[0]) || names.value[0] || '';
    }, { immediate: true });

    const onProfilePick = () => { profilePickedByUser = true; };
    const profileList = computed(() => playerMatches(matches.value, profileName.value));
    const profileListNewest = computed(() => [...profileList.value].reverse());
    const summary = computed(() => playerSummary(profileList.value));
    const badges = computed(() => computeBadges(profileList.value));
    const earnedCount = computed(() => badges.value.filter(b => b.earned).length);

    const tiles = computed(() => {
      const s = summary.value;
      return [
        { label: 'Kampe', value: s.matches },
        { label: 'Sejre', value: s.matches ? `${s.wins} (${s.winPct}%)` : '–' },
        { label: 'Gennemsnit', value: formatNumber(s.average) },
        { label: 'Bedste kamp', value: formatNumber(s.bestAverage) },
        { label: '180', value: s.n180 },
        { label: 'Checkout %', value: formatPct(s.checkouts, s.doubleDarts) },
        { label: 'Højeste checkout', value: s.highestCheckout || '–', gold: true },
        { label: 'Bedste leg', value: s.bestLeg !== null ? `${s.bestLeg} darts` : '–' },
      ];
    });

    const chartPoints = computed(() => profileList.value
      .map(e => ({
        y: metric.value === 'avg' ? e.avg : e.checkoutPct,
        label: formatDate(e.date),
        sub: `${e.result === 'win' ? 'Sejr' : (e.result === 'loss' ? 'Tab' : 'Uafgjort')} ${e.myLegs}–${e.oppLegs} mod ${e.oppName}`,
      }))
      .filter(p => p.y !== null && p.y !== undefined && !Number.isNaN(p.y))
      .map(p => ({ ...p, y: Math.round(p.y * 10) / 10 })));

    const h2hRows = computed(() => {
      const { a, b } = h2h.value;
      const avgA = average(a.scored, a.visits);
      const avgB = average(b.scored, b.visits);
      const pctA = a.doubleDarts > 0 ? a.checkouts / a.doubleDarts : null;
      const pctB = b.doubleDarts > 0 ? b.checkouts / b.doubleDarts : null;
      const higher = (x, y) => (x === null || y === null || x === y ? null : (x > y ? 'a' : 'b'));
      const lower = (x, y) => (x === null || y === null || x === y ? null : (x < y ? 'a' : 'b'));
      return [
        { label: 'Legs vundet', a: a.legs, b: b.legs, winner: higher(a.legs, b.legs) },
        { label: 'Gennemsnit', a: formatNumber(avgA), b: formatNumber(avgB), winner: higher(avgA, avgB) },
        { label: '180', a: a.n180, b: b.n180, winner: higher(a.n180, b.n180) },
        { label: '140+', a: a.n140, b: b.n140, winner: higher(a.n140, b.n140) },
        { label: '100+', a: a.n100, b: b.n100, winner: higher(a.n100, b.n100) },
        { label: 'Højeste score', a: a.highScore || '–', b: b.highScore || '–', winner: higher(a.highScore, b.highScore) },
        { label: 'Højeste checkout', a: a.highestCheckout || '–', b: b.highestCheckout || '–', winner: higher(a.highestCheckout, b.highestCheckout) },
        { label: 'Checkout %', a: formatPct(a.checkouts, a.doubleDarts), b: formatPct(b.checkouts, b.doubleDarts), winner: higher(pctA, pctB) },
        { label: 'Bedste leg', a: a.bestLeg !== null ? `${a.bestLeg} darts` : '–', b: b.bestLeg !== null ? `${b.bestLeg} darts` : '–', winner: lower(a.bestLeg, b.bestLeg) },
      ];
    });

    const recordCards = computed(() => {
      const r = records(matches.value);
      const who = (rec) => (rec ? `${rec.name} · ${formatDate(rec.date)}` : 'Ingen endnu');
      return [
        { label: 'Højeste checkout', value: r.highestCheckout ? r.highestCheckout.value : '–', who: who(r.highestCheckout), gold: true },
        { label: 'Bedste leg', value: r.bestLeg ? `${r.bestLeg.value} darts` : '–', who: who(r.bestLeg) },
        { label: 'Højeste kampgns.', value: r.bestAverage ? formatNumber(r.bestAverage.value) : '–', who: who(r.bestAverage) },
        { label: 'Flest 180 i en kamp', value: r.most180 ? r.most180.value : '–', who: who(r.most180) },
      ];
    });

    // Forget the running match id so the scoreboard doesn't write it back.
    const detachCurrentMatch = () => update(firebaseRef(database, 'scores'), { currentMatchId: null, matchStartedAt: null });

    // Sides of a multi-player match for the list: teams are combined.
    const matchSides = (m) => {
      const players = allPlayers(m);
      let sides;
      if (m.teams) {
        sides = m.teams.map((t, i) => {
          const ps = t.map(idx => players[idx]).filter(Boolean);
          const scored = ps.reduce((a, p) => a + (p.scored || 0), 0);
          const visits = ps.reduce((a, p) => a + (p.visits || 0), 0);
          return { key: `t${i}`, name: ps.map(p => p.name).join(' & '), legs: (ps[0] && ps[0].legs) || 0, avg: average(scored, visits) };
        });
      } else {
        sides = players.map((p, i) => ({ key: `p${i}`, name: p.name, legs: p.legs || 0, avg: average(p.scored || 0, p.visits || 0) }));
      }
      const top = Math.max(...sides.map(x => x.legs));
      const leaders = sides.filter(x => x.legs === top).length;
      return sides.map(x => ({ ...x, won: x.legs === top && leaders === 1 })).sort((a, b) => b.legs - a.legs);
    };

    const deleteMatch = async (m) => {
      const label = isOneVsOne(m)
        ? `${m.players.p1.name} ${m.players.p1.legs}–${m.players.p2.legs} ${m.players.p2.name}`
        : matchSides(m).map(x => `${x.name} ${x.legs}`).join(', ');
      const live = m.id === currentMatchId.value;
      const extra = live ? '\n\nKampen er i gang. Den bliver gemt igen som en ny kamp, når næste leg er vundet.' : '';
      if (await showConfirm(`${label}, ${formatDate(m.startedAt)}.${extra}`, { title: 'Slet kamp?', confirmText: 'Slet', danger: true })) {
        if (live) detachCurrentMatch();
        remove(firebaseRef(database, `history/matches/${m.id}`));
      }
    };

    const deleteAll = async () => {
      const n = matches.value.length;
      if (await showConfirm(`Alle ${n} kampe i historikken bliver slettet. Det kan ikke fortrydes.`, { title: 'Slet alle kampe?', confirmText: 'Slet alle', danger: true })) {
        if (currentMatchId.value) detachCurrentMatch();
        remove(firebaseRef(database, 'history/matches'));
      }
    };

    onMounted(() => {
      unsubscribers.push(onValue(firebaseRef(database, 'history/matches'), (snap) => {
        raw.value = snap.val();
        loading.value = false;
      }, () => { loading.value = false; }));
      unsubscribers.push(onValue(firebaseRef(database, 'history/cricket'), (snap) => {
        rawCricket.value = snap.val();
      }, () => {}));
      unsubscribers.push(onValue(firebaseRef(database, 'scores'), (snap) => {
        const d = snap.val() || {};
        currentMatchId.value = d.currentMatchId || null;
        scoreboardNames.value = [d.player1Name || '', d.player2Name || ''];
      }));
    });
    onUnmounted(() => unsubscribers.forEach(u => u()));

    return {
      loading, matches, names, playerA, playerB, h2h, h2hRows, recordCards,
      currentMatchId, backLink, deleteMatch, deleteAll, formatDate, formatNumber, average,
      cricketMatches, cricketTable, cricketModeLabel, deleteCricket,
      tab, metric, profileName, onProfilePick, isOneVsOne, matchSides, profileListNewest, tiles, chartPoints, badges, earnedCount, iconPaths: ICON_PATHS,
    };
  },
};
